SELECT
	 LCL.[apuk_localgroupid]
	,LCL.[apuk_name]
	,LCL.[apuk_code]
	,LCL.[apuk_regionid]
	,LCL.[apuk_regionid_name]
	,LCL.[apuk_worldregionid]
	,LCL.[apuk_worldregionid_name]
	,LCL.[apuk_countryid]
	,CNT.apuk_code AS country_two_char_code
	,CCM.Three_Char_Code AS country_three_char_code
	,LCL.[apuk_countryid_name]
	,LCL.[apuk_reportingregion]
	,LCL.[apuk_reportingregion_name]
	,LCL.[apuk_subregion]
	,LCL.[apuk_subregion_name]
	,LCL.[apuk_reportingsubworldregion]
	,LCL.[apuk_reportingsubworldregion_name]
	,LCL.[statecode]
	,LCL.[StateCode_Description]
	,LCL.[statuscode]
	,LCL.[StatusCode_Description]
	,M.Fin_Market
	,M.Fin_Region
	,M.Fin_World_Region
	,CASE WHEN M.Fin_Market = 'UK' THEN LCL.[apuk_subregion_name] ELSE [apuk_countryid_name] END AS 'UK Region'
	,CASE 
		WHEN Fin_Region IN('ANZ', 'Greater China', 'North Asia','South East Asia' ) THEN 'APAC' 
		WHEN Fin_region IN ('MENA', 'SSA') THEN 'MEA'
		WHEN CASE WHEN M.Fin_Market = 'UK' THEN LCL.[apuk_subregion_name] ELSE [apuk_countryid_name] END = 'Reunion' THEN 'MEA'
		WHEN CASE WHEN M.Fin_Market = 'UK' THEN LCL.[apuk_subregion_name] ELSE [apuk_countryid_name] END = 'The Democratic Republic of the Congo' THEN 'MEA'
		ELSE Fin_region 
	END AS Market_reporting_region
	,M.Budget_Region
FROM [synapse_ce].[vwLocalGroup] LCL
LEFT JOIN synapse_ce.vwCountry CNT 
	ON CNT.apuk_countryid = LCL.apuk_countryid
LEFT JOIN Static.tblCountryCodeMapping CCM 
	ON CCM.Two_Char_Code = CNT.apuk_code
LEFT JOIN Markets M 
	ON M.country_three_char_code = CCM.Three_Char_Code
